    "clinicalCase": "Um escolar com 8 anos, acompanhado da mãe, chega à unidade básica de saúde com queixa de estar muito cansado e sonolento. A mãe refere que, há aproximadamente 20 dias, ele vem perdendo peso (cerca de 5 kg). Ela relata ainda que o filho, embora tenha controle esfincteriano noturno desde os 5 anos, tem agora apresentado enurese noturna, desde o início do quadro. Conta também que, no mesmo período, passou a demonstrar apetite exagerado e que, há 5 dias, começou a apresentar dor abdominal de moderada intensidade, sem localização específica, intermitente, associada a náuseas e vômitos (1 vez ao dia). Ao exame físico, a criança se apresenta em regular estado geral, hipocorado (+1/+4), afebril, acianótico, mucosas secas, hipoativo, fácies de dor, normotenso. À ausculta pulmonar, não há ruídos adventícios; frequência respiratória de 50 incursões respiratórias por minuto, com movimentos respiratórios amplos; ausculta cardíaca sem alterações, frequência cardíaca de 90 batimentos por minuto; abdome doloroso à palpação profunda, com ruídos hidroaéreos presentes, sem massas ou visceromegalias. Após o manejo inicial, qual das opções a seguir apresenta o seguimento a longo prazo adequado para essa doença?",
