    "clinicalCase": "Uma paciente com 24 anos, estudante de medicina, procura atendimento no ambulatório de uma universidade com história de febre não aferida e mal-estar generalizado iniciados há cerca de 48 horas. Conta que hoje começou a apresentar cefaleia intensa, motivo de sua procura por assistência. Informa ter tido varicela e rubéola quando criança. Refere ter sido vacinada na infância e que, quando entrou na faculdade, tomou uma dose de dT e da vacina para hepatite B, mas não completou o esquema. Nega vacinação em campanhas, pois teve rubéola na infância. Ao exame físico, apresenta frequência respiratória de 24 incursões respiratórias por minuto, frequência cardíaca de 100 batimentos por minuto, pressão arterial de 120 × 80 mmHg, temperatura axilar de 38,8 °C; mucosas normocoradas, hipohidratadas (+1/+4), escleróticas anictéricas; aparelho respiratório: murmúrio vesicular universalmente audível, ausência de ruídos adventícios; aparelho cardiovascular: ritmo cardíaco regular em dois tempos, bulhas normofonéticas, sem sopros ou atritos; abdome: flácido, peristáltico, sem visceromegalias. No exame neurológico está acordada, lúcida, movimenta os quatro membros, sem déficit focal aparente, com rigidez de nuca (+3/+4), sinal de Kernig e sinal de Brudzinski presentes. Não foram observadas lesões cutâneas ou mucosas. Na fundoscopia ocular: nervos óticos bem visualizados, sem alterações. Com relação à abordagem diagnóstica, assinale a opção correta.",
