    "clinicalCase": "Um homem com 78 anos, acamado há meses em função de quadro demencial avançado, chega à unidade de emergência com quadro de rebaixamento do nível de consciência, febre e hipotensão arterial. Segundo familiares, o paciente vem apresentando tosse desde a ocorrência, há 3 dias, de episódio compatível com broncoaspiração durante tentativa de alimentação por via oral. Relatam que, nos últimos 2 dias, ele passou a se mostrar mais apático, não interagindo minimamente com os familiares, nem aceitando alimentação e que, no dia de hoje, surgiu febre e a acompanhante aferiu pressão arterial de 90 × 60 mmHg, uma queda de cerca de 40 mmHg na pressão sistólica em relação ao parâmetro habitual do paciente. Ao exame físico, é confirmada hipotensão arterial sistêmica (88 × 48 mmHg), além de sonolência (escore de coma de Glasgow de 9 pontos), desidratação (+2/+4), descoramento de mucosas (+1/+4), taquicardia (120 batimentos por minuto), taquipneia (26 incursões respiratórias por minuto) e presença de roncos difusos, com estertores crepitantes na base direita. Exames laboratoriais iniciais revelam anemia (hemoglobina de 8,5 g/dL - valor de referência [VR]: 13- 17 g/dL), elevação de creatinina (2,3 mg/dL - VR: 0,8- 1,2 mg/dL), ureia (102 mg/dL - VR: 20-40 mg/dL) e lactato (5,1 mmol/L - VR: <= 2,0 mmol/L), além de acidose metabólica e hipoxemia. São colhidas hemoculturas. O paciente é monitorizado adequadamente, submetido a oferta suplementar de oxigênio, e inicia-se o tratamento indicado para o quadro clínico que apresenta. Além da antibioticoterapia de amplo espectro adequada, a conduta prioritária a ser adotada para esse paciente ainda nas primeiras horas de abordagem é",
