    "clinicalCase": "Uma mulher com 40 anos é encaminhada da unidade básica de saúde para o ambulatório de referência em neurologia devido a cefaleia. Relata que apresenta episódios de cefaleia hemicraniana, acompanhada de náuseas e escotomas visuais, desde a adolescência, e que, aos 30 anos, fez tratamento com propranolol por 1 ano, o que reduziu significativamente o número de crises de cefaleia, que passaram a ocorrer 1 a 2 vezes no mês. Acrescenta que, no entanto, há 3 meses, a frequência dos episódios aumentou; tornaram-se diários, com despertares noturnos devido a dor, aumento da intensidade e, no momento, descreve a cefaleia como holocraniana. Nessa situação, a conduta adequada para o caso deve ser",
