    "clinicalCase": "Um paciente com 65 anos procura a unidade de pronto atendimento com queixa de ter acordado com dor abdominal, súbita, difusa, de intensidade crescente. Conta que fez uso de medicação sintomática e apresentou 2 episódios de vômitos. Nega sintomas urinários e alteração do hábito intestinal. Relata tabagismo (consumo de 60 maços/ano) e etilismo habitual (2 doses de destilado/dia), além das seguintes comorbidades: hipertensão arterial, em uso de atenolol, losartana, aspirina e sinvastatina; infarto agudo do miocárdio há 10 anos. Acrescenta que passou por uma cirurgia prévia, de urgência, de úlcera no estômago há 18 anos. Ao exame físico, apresenta-se: obeso, em regular estado geral, agitado. Registram-se, ainda: pressão arterial de 100 × 60 mmHg; frequência cardíaca de 110 batimentos por minuto; frequência respiratória de 20 incursões respiratórias por minuto; temperatura axilar de 37,8 °C; estando o paciente ictérico (+1/+4), corado, desidratado (+1/+4), com abdome normotenso, doloroso à palpação profunda difusamente, sem sinais de irritação peritoneal. Resultados de seus exames laboratoriais apresentam: hemoglobina: 13 g/dL, leucócitos: 14.000/mm3, amilase: 238 U/L, lipase: 130 U/L, Proteína C Reativa: 8 mg/L, gasometria venosa mostrando Ph: 7,32 e lactato: 27 mg/dL. Nesse caso, a principal hipótese diagnóstica é de abdome agudo",
